        if "Drug Allergies" in patient_profile and patient_profile["Drug Allergies"]:
            risk_factor_present = True
    elif risk_category == "Drug-Drug Interaction Risk":
        if "Current Medications" in patient_profile and patient_profile["Current Medications"]:
            for medication in patient_profile["Current Medications"]:
                if medication in physician_assessment["Recommended Medication"]:
                    risk_factor_present = True
                    break
    elif risk_category == "Drug-Food Interaction Risk":
        if "Foods (Last 24h)" in patient_profile and patient_profile["Foods (Last 24h)"]:
