    elif risk_category == "Tobacco Use Risk":
        if "Tobacco Use" in patient_profile and patient_profile["Tobacco Use"]:
            risk_factor_present = True
    elif risk_category == "Substance Use Risk":
        if "Substance Use" in patient_profile and patient_profile["Substance Use"]:
            risk_factor_present = True
    elif risk_category == "Caffeine Intake Risk":
        if "Caffeine Intake" in patient_profile and patient_profile["Caffeine Intake"]:
            risk_factor_present = True
    elif risk_category == "Weight/BMI Risk":
        if "Weight (kg)" in patient_profile and patient_profile["Weight (kg)"] < 50:
            risk_factor_present = True
    elif risk_category == "Age Risk":
        if "Age" in patient_profile and patient_profile["Age"] < 18:
            risk_factor_present = True

    # Add the risk factor to the reasoning list if it was found
    if risk_factor_present:
        reasoning.append(f"{risk_category}: Risk factor present")

# Evaluate each risk category individually and determine whether the patient is at risk for that category
risk_analysis = {}
for risk_category in risk_categories:
