# Output the results as a JSON object with the specified structure
output = {
    "reasoning": "\n".join(reasoning),
    "risk_analysis": risk_analysis,
    "is_safe": is_safe
}

with open("output.json", "w") as f:
    json.dump(output, f, indent=4)

